-- Touches: iam.get_auth_user_snapshot
-- 8-B (2026-10-11): KI-05 — get_tenant_readiness / activate_tenant removed (legacy readiness flow).
-- Promoted from _drafts/016_iam_tenant_readiness_activate.sql
-- Generated by tools/vet45_supabase_migrate/bin/promote_drafts.dart

create or replace function iam.get_auth_user_snapshot(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = iam, auth, pg_temp
as $$
declare
  v_user record;
  v_status text;
begin
  select
    u.id,
    u.email_confirmed_at,
    u.banned_until
  into v_user
  from auth.users u
  where u.id = p_user_id;

  if v_user.id is null then
    return jsonb_build_object(
      'user_id', p_user_id,
      'account_status', 'unavailable',
      'email_verified', false,
      'evaluated_at', now()
    );
  end if;

  if v_user.banned_until is not null and v_user.banned_until > now() then
    v_status := 'suspended';
  else
    v_status := 'active';
  end if;

  return jsonb_build_object(
    'user_id', v_user.id,
    'account_status', v_status,
    'email_verified', v_user.email_confirmed_at is not null,
    'evaluated_at', now()
  );
end;
$$;

-- Only IAM security-definer callers and the service role may execute. Role
-- `authenticated`/`anon`/`public` cannot invoke the Auth snapshot directly.
revoke all on function iam.get_auth_user_snapshot(uuid) from public, anon, authenticated;
grant execute on function iam.get_auth_user_snapshot(uuid) to service_role;
